// src/scripts/seedProfileTypes.js
import 'dotenv/config'; // <-- this must come first
import connectDB, { sequelize } from "../database/connectDB.js";
import ProfileType from "../models/ProfileType.model.js";
import PlatformLink from "../models/PlatformLink.model.js";

async function seedProfileTypes() {
 
  // PERSONAL
  await ProfileType.findOrCreate({
    where: { type: "PERSONAL" },
    defaults: {
      name: "Personal",
      category: "NETWORK",
      description: "Personal profile",
    },
  });

  // BUSINESS
  await ProfileType.findOrCreate({
    where: { type: "BUSINESS" },
    defaults: {
      name: "Business",
      category: "NETWORK",
      description: "Business profile",
    },
  });

  await ProfileType.findOrCreate({
    where: { type: "SOS" },
    defaults: {
      name: "Sos",
      category: "RESCUE_ID",
      description: "Sos profile",
    },
  });

  await ProfileType.findOrCreate({
    where: { type: "PET" },
    defaults: {
      name: "Pet",
      category: "RESCUE_ID",
      description: "Pet profile",
    },
  });

  await ProfileType.findOrCreate({
    where: { type: "STORE_FRONT" },
    defaults: {
      name: "Storefront",
      category: "STORE_FRONT",
      description: "Storefront profile",
    },
  });
}

