async function seedPlatformLinks() {
  const platforms = [
    {
      name: "instagram",
      type: "social",
      start_link: "https://www.instagram.com",
      default_icon: INSTAGRAM_DEFAULT_SVG,
    },
    {
      name: "snapchat",
      type: "social",
      start_link: "https://www.snapchat.com",
      default_icon: SNAPCHAT_DEFAULT_SVG,
    },
    {
      name: "facebook",
      type: "social",
      start_link: "https://www.facebook.com",
      default_icon: FACEBOOK_DEFAULT_SVG,
    },
    {
      name: "youtube",
      type: "social",
      start_link: "https://www.youtube.com",
      default_icon: YOUTUBE_DEFAULT_SVG,
    },
    {
      name: "twitter",
      type: "social",
      start_link: "https://www.twitter.com",
      default_icon: TWITTER_DEFAULT_SVG,
    },
    {
      name: "discord",
      type: "social",
      start_link: "https://discord.com",
      default_icon: DISCORD_DEFAULT_SVG,
    },
  ];

  for (const platform of platforms) {
    await PlatformLink.findOrCreate({
      where: { name: platform.name },
      defaults: platform,
    });
  }
}

async function runSeed() {
  try {
    await connectDB();
    // or: await sequelize.authenticate();

    await seedProfileTypes();
    await seedPlatformLinks();

    console.log("✅ Profile types & platform links seeded successfully");
    process.exit(0);
  } catch (err) {
    console.error("❌ Failed to seed:", err);
    process.exit(1);
  }
}

runSeed();
